// Generated by Cypress Author on 2026-11-10.
import type { UserDto } from "@campushub/shared";
import { buildUser } from "./data";

declare global {
  namespace Cypress {
    interface Chainable {
      /**
       * Stubs the API calls every signed-in page makes. Any /api request a spec
       * does not stub itself gets a 404, so nothing reaches a real server.
       */
      stubApi(user?: UserDto): Chainable<void>;
      /** Opens a page with a saved session for `user`, skipping the login form */
      visitSignedIn(path: string, user?: UserDto): Chainable<Cypress.AUTWindow>;
      /** Fills the Fanshawe ID box, which adds @fanshaweonline.ca itself */
      typeFanshaweId(selector: string, id: string): Chainable<JQuery<HTMLElement>>;
    }
  }
}

Cypress.Commands.add("stubApi", (user = buildUser()) => {
  // Registered first, so the specific stubs added later take precedence
  cy.intercept("/api/**", { statusCode: 404, body: { error: "Not stubbed in this test" } });
  // Live updates need the API's Socket.IO server; the specs run without it
  cy.intercept("/socket.io/**", { statusCode: 503, body: "" });
  cy.intercept("GET", "/api/profile/me", { body: user }).as("profile");
  cy.intercept("GET", "/api/conversations/counts", { body: { unreadTotal: 0, requestCount: 0 } });
});

Cypress.Commands.add("visitSignedIn", (path, user = buildUser()) => {
  return cy.visit(path, {
    onBeforeLoad(win) {
      // The same keys AuthProvider saves after a real login
      win.localStorage.setItem("campushub_token", "e2e-token");
      win.localStorage.setItem("campushub_user", JSON.stringify(user));
      win.localStorage.setItem("campushub_last_active", Date.now().toString());
    },
  });
});

Cypress.Commands.add("typeFanshaweId", (selector, id) => {
  return cy.get(selector).clear().type(id);
});
